#!/usr/bin/env python3
"""Builds podcast_script_infohandicap{,_fr,_de,_lb}.md from build/infohandicap_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "infohandicap"
HEAD = {
 "en": ('# Podcast Script — "Info-Handicap – Nothing About Us Without Us"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « Info-Handicap – Rien sur nous, sans nous »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Info-Handicap – Nichts über uns ohne uns“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „Info-Handicap – Näischt iwwer eis ouni eis“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 11, "fr": 10, "de": 12, "lb": 11}   # EN 10:45, FR 10:19, DE 11:35 (27 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources: info-handicap.lu (Info-Handicap – Conseil National des Personnes Handicapées asbl), consulted on 27 November 2026 in German and French — home page (national council and central contact point; active since 1993; member associations; motto \"Nothing about us without us\"); \"About us\" (members, board elected by the members, team; four areas of work; inclusive approach; motto from the European Disability Forum; 2021 census: nearly 15% of the population has a disability, most often visual, motor and hearing impairments; higher unemployment); \"Mission, vision and values\" (political representation, Info-Handicap represents Luxembourg in the European Disability Forum; EureWelcome label; MOSAIK; SAMT; awareness campaigns all year round); \"Our history\" (founded in 1993; legal information service since 1999; recognised by the Ministry of Education as a training centre since 2012; national action plans for the UN Convention on the Rights of Persons with Disabilities); \"Our members\" and \"Become a member\" (organisations with at least one activity in the field of disability); \"Information and advice\" (Info-Conseil: for everyone; most frequent questions on work, education and accessibility; legal consultation in some cases; civil party before the courts; 366 466, info@iha.lu); \"Contact\" (office in Luxembourg City, Monday to Friday, advice by appointment); \"Guide du Handicap\" (six guides to download); \"Accessibility\" (CTA training for technical accessibility inspectors; EureWelcome; accessible communication: easy-to-read language, sign language); \"SAMT\" (preliminary interview, personal learning plan, preparation for the unexpected; all public transport, one route or one means of transport); \"Adapto\"; \"Training\" and \"Bewosst workshops\" (two hours, small groups, in Luxembourgish, French, German or English, exchange with people concerned, certificate of attendance; workshop on hidden disabilities); \"Hidden Disabilities Sunflower\" (lanyard and card, free of charge, no registration or proof, at the office on weekdays); \"MOSAIK Kultur Inklusiv\" (network coordinated by Info-Handicap); \"Elections\" (since the law of 29 June 2023, people under full guardianship can vote; information events and workshops); \"Donations\". Durable wording only: no exact numbers of members (the site gives 65) or staff, no opening times, no fees, no names, no street address; the census figure is given as \"about one person in seven\". The laws on accessibility are explained in the accessibility episode, voting in the episode I Can Vote. The opening scene is an illustration by the hosts. General information only. Accurate as of November 2026.*",
 "fr": "*Sources : info-handicap.lu (Info-Handicap – Conseil National des Personnes Handicapées asbl), consulté le 27 novembre 2026 en allemand et en français — page d'accueil (conseil national et point de contact central ; actif depuis 1993 ; associations membres ; devise « Rien sur nous, sans nous ») ; « À propos » (membres, conseil d'administration élu par les membres, équipe ; quatre domaines de travail ; approche inclusive ; devise du Forum européen des personnes handicapées ; recensement de 2021 : près de 15 % de la population a un handicap, le plus souvent visuel, moteur ou auditif ; chômage plus élevé) ; « Mission, vision et valeurs » (représentation politique, représentation du Luxembourg au Forum européen des personnes handicapées ; label EureWelcome ; MOSAIK ; SAMT ; campagnes de sensibilisation toute l'année) ; « Notre histoire » (fondée en 1993 ; service d'information juridique depuis 1999 ; reconnue par le ministère de l'Éducation comme centre de formation depuis 2012 ; plans d'action nationaux pour la Convention des Nations unies relative aux droits des personnes handicapées) ; « Nos membres » et « Devenir membre » ; « Information et conseil » (Info-Conseil : pour tous ; questions les plus fréquentes sur le travail, l'éducation et l'accessibilité ; consultation juridique dans certains cas ; partie civile devant les tribunaux ; 366 466, info@iha.lu) ; « Contact » (bureau à Luxembourg-ville, du lundi au vendredi, entretien sur rendez-vous) ; « Guide du Handicap » (six guides à télécharger) ; « Accessibilité » (formation CTA ; EureWelcome ; communication accessible : FALC, langue des signes) ; « SAMT » ; « Adapto » ; « Formation continue » et « Workshops Bewosst » (deux heures, petits groupes, en luxembourgeois, français, allemand ou anglais, échange avec des personnes concernées, certificat ; atelier sur les handicaps invisibles) ; « Hidden Disabilities Sunflower » (lanière et carte gratuites, sans inscription ni justificatif, au bureau en semaine) ; « MOSAIK Kultur Inklusiv » ; « Élections » (depuis la loi du 29 juin 2023, les personnes sous tutelle peuvent voter ; séances d'information et ateliers) ; « Dons ». Formulations durables uniquement : pas de nombre exact de membres (le site en indique 65) ni de collaborateurs, pas d'horaires, pas de tarifs, pas de noms, pas d'adresse ; le chiffre du recensement est donné comme « environ une personne sur sept ». Les lois sur l'accessibilité sont expliquées dans l'épisode sur l'accessibilité, le vote dans l'épisode « Je peux voter ». La scène d'ouverture est une illustration des animateurs. Informations générales uniquement. Exact en novembre 2026.*",
 "de": "*Quellen: info-handicap.lu (Info-Handicap – Conseil National des Personnes Handicapées asbl), abgerufen am 27. November 2026 auf Deutsch und Französisch — Startseite (nationaler Rat und zentrale Anlaufstelle; seit 1993 aktiv; Mitgliedsvereinigungen; Motto „Nichts über uns ohne uns“); „Über uns“ (Mitglieder, von den Mitgliedern gewählter Verwaltungsrat, Team; vier Arbeitsbereiche; inklusiver Ansatz; Motto des Europäischen Behindertenforums; Volkszählung 2021: fast 15 % der Bevölkerung haben eine Behinderung, am häufigsten Seh-, Bewegungs- und Hörbeeinträchtigungen; höhere Arbeitslosigkeit); „Mission, Vision und Werte“ (politische Vertretung, Vertretung Luxemburgs im Europäischen Behindertenforum; Label EureWelcome; MOSAIK; SAMT; Kampagnen das ganze Jahr über); „Unsere Geschichte“ (gegründet 1993; juristischer Informationsdienst seit 1999; seit 2012 vom Bildungsministerium als Weiterbildungszentrum anerkannt; nationale Aktionspläne zur UN-Behindertenrechtskonvention); „Unsere Mitglieder“ und „Mitglied werden“; „Information und Beratung“ (Info-Conseil: für alle; häufigste Fragen zu Arbeit, Bildung und Barrierefreiheit; in manchen Fällen Rechtsberatung; Nebenkläger vor Gericht; 366 466, info@iha.lu); „Kontakt“ (Büro in Luxemburg-Stadt, Montag bis Freitag, Beratung nach Vereinbarung); „Guide du Handicap“ (sechs Ratgeber zum Herunterladen); „Barrierefreiheit“ (CTA-Ausbildung; EureWelcome; barrierefreie Kommunikation: Leichte Sprache, Gebärdensprache); „SAMT“; „Adapto“; „Weiterbildung“ und „Workshops Bewosst“ (zwei Stunden, kleine Gruppen, auf Luxemburgisch, Französisch, Deutsch oder Englisch, Austausch mit Betroffenen, Teilnahmebescheinigung; Workshop zu unsichtbaren Beeinträchtigungen); „Hidden Disabilities Sunflower“ (Band und Karte kostenlos, ohne Anmeldung und Nachweis, im Büro an Werktagen); „MOSAIK Kultur Inklusiv“; „Wahlen“ (seit dem Gesetz vom 29. Juni 2023 dürfen Menschen unter Vormundschaft wählen; Informationsveranstaltungen und Workshops); „Spenden“. Nur dauerhafte Angaben: keine genaue Zahl der Mitglieder (die Website nennt 65) oder Mitarbeitenden, keine Öffnungszeiten, keine Preise, keine Namen, keine Adresse; die Zahl der Volkszählung wird als „etwa jeder siebte Mensch“ angegeben. Die Gesetze zur Barrierefreiheit erklärt die Folge über Barrierefreiheit, das Wählen die Folge „Ich kann wählen“. Die Eingangsszene ist eine Veranschaulichung der Moderatoren. Nur allgemeine Informationen. Stand: November 2026.*",
 "lb": "*Quellen: info-handicap.lu (Info-Handicap – Conseil National des Personnes Handicapées asbl), consultéiert de 27. November 2026 op Däitsch an op Franséisch. Fräi Iwwersetzung: de Site huet keng lëtzebuergesch Versioun. Keng genau Zuel vu Memberen, keng Ëffnungszäiten, keng Präisser, keng Nimm a keng Adress. Nëmmen allgemeng Informatiounen. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/infohandicap_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 44, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
